from pathlib import Path
P=Path('.')
nav='<div id="nav"></div>'
foot='<footer class="footer"><div class="container">© 2026 Concord’s as your Tutor • Learn from your own notes.</div></footer>'
common='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Concord’s as your Tutor — your personal study partner, powered by your own notes."><title>Concord’s as your Tutor</title><link rel="stylesheet" href="styles.css"><link rel="manifest" href="manifest.webmanifest"><meta name="theme-color" content="#0b1020"><meta name="mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-title" content="Concord Tutor"><link rel="icon" type="image/png" sizes="32x32" href="favicon-32.png"><link rel="apple-touch-icon" href="apple-touch-icon.png"></head><body>'''
def write(name,body,scripts=''):
    Path(name).write_text(common+nav+body+foot+'<script src="pwa.js"></script><script src="config.js"></script><script src="tracker.js"></script><script src="app.js"></script>'+scripts+'</body></html>')
write('index.html','''<main><section class="hero"><div class="container hero-grid"><div id="welcome"><span class="eyebrow">Personal learning • Local-first</span><h1 class="title">Concord’s <span class="gradient">as your Tutor</span></h1><p class="lead">Your personal study partner, powered by your own notes. Upload your lecture material, choose your question count, and test yourself with a fresh randomized quiz.</p><div class="actions"><a class="btn primary" href="student.html">Get started →</a><a class="btn secondary" href="about.html">How it works</a></div></div><div class="card"><div class="stat"><div class="num">01</div><div><b>Build your profile</b><div class="muted">Tell the tutor who you are and what you study.</div></div></div><hr style="border:0;border-top:1px solid var(--border);margin:20px 0"><div class="stat"><div class="num">02</div><div><b>Upload your notes</b><div class="muted">Your material becomes the knowledge source.</div></div></div><hr style="border:0;border-top:1px solid var(--border);margin:20px 0"><div class="stat"><div class="num">03</div><div><b>Quiz. Learn. Repeat.</b><div class="muted">Get instant feedback and track your progress.</div></div></div></div></div></section><section class="section"><div class="container"><h2>Everything stays in your browser</h2><p class="muted">Profile and progress are stored with localStorage. Your uploaded study text is processed locally by the browser for this demo build.</p><div class="cards"><div class="card feature"><div class="ico">📚</div><h3>Notes-first questions</h3><p>Question templates are created from readable content inside your uploaded material instead of unrelated generic questions.</p></div><div class="card feature"><div class="ico">⚡</div><h3>Instant feedback</h3><p>Multiple-choice answers are checked directly. Theory responses are compared against key concepts and can receive partial credit.</p></div><div class="card feature"><div class="ico">📈</div><h3>Progress tracking</h3><p>See previous scores, average performance and your best attempt on the Progress page.</p></div></div></div></section></main>''')
write('student.html','''<main class="container"><div class="form card"><span class="eyebrow">Before you start</span><h1>Who is taking this quiz?</h1><p class="muted">Enter the student’s name. It is used for feedback and for the final Hurray / Shame result, so each student sees their own name.</p><form id="studentForm"><div class="field"><label for="studentName">Student name</label><input id="studentName" required name="studentName" autocomplete="off" placeholder="e.g. Ama Mensah"></div><div class="actions"><button class="btn primary" type="submit">Next →</button><button id="continueAs" class="btn secondary hidden" type="button"></button></div></form><div class="notice small" style="margin-top:20px">Your tutor can see your name, school details, the name of the file you upload and your quiz progress, so they can follow how you are learning.</div></div></main>''')
write('profile.html','''<main class="container"><div class="form card"><span class="eyebrow">Step 1 of 3</span><h1>Tell your tutor about you</h1><p class="muted">This is saved locally so you won’t need to enter it again.</p><div class="stepper"><div class="step on"></div><div class="step"></div><div class="step"></div></div><form id="profileForm"><div class="field"><label>Full name</label><input required name="name" placeholder="e.g. Concord Essuman"></div><div class="two"><div class="field"><label>School / University</label><input required name="school" placeholder="e.g. KNUST"></div><div class="field"><label>Programme / Course</label><input required name="programme" placeholder="e.g. BSc Computer Science"></div></div><div class="two"><div class="field"><label>Level / Class</label><input required name="level" placeholder="e.g. Level 100"></div><div class="field"><label>Subjects / Courses</label><input required name="subjects" placeholder="e.g. Calculus, ICT, Economics"></div></div><button class="btn primary" type="submit">Next →</button></form></div></main>''')
write('upload.html','''<main class="container"><div class="form card"><span class="eyebrow">Step 2 of 3</span><h1>Upload your study material</h1><p class="muted">PDF, DOCX, TXT and MD are supported. The readable text becomes the question source.</p><div class="stepper"><div class="step on"></div><div class="step on"></div><div class="step"></div></div><div class="field"><label for="file">Choose study material</label><input id="file" type="file" accept=".pdf,.docx,.txt,.md,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document,text/plain"></div><div id="selected" class="muted small"></div><div id="status" class="status hidden"></div><div class="actions"><button id="continue" class="btn primary">Process material & continue →</button><a class="btn secondary" href="index.html">Home</a></div><div class="notice small">Tip: for best results, upload lecture notes with clear headings and explanations. Scanned image-only PDFs may not contain readable text.</div></div></main>''','''<script src="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.min.mjs" type="module"></script><script type="module">import * as pdfjsLib from 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.min.mjs';pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.worker.min.mjs';window.pdfjsLib=pdfjsLib;</script><script src="https://unpkg.com/mammoth@1.8.0/mammoth.browser.min.js"></script>''')
write('questions.html','''<main class="container"><div class="form card"><span class="eyebrow">Step 3 of 3</span><h1>How many questions?</h1><p id="available" class="muted"></p><div class="stepper"><div class="step on"></div><div class="step on"></div><div class="step on"></div></div><div class="chips">'''+''.join(f'<button class="chip count" data-count="{n}">{n} Questions</button>' for n in range(20,26))+'''</div><div class="actions"><button id="start" class="btn primary">Start randomized quiz →</button><a href="upload.html" class="btn secondary">Change material</a></div><div class="notice small">If your material contains fewer unique question templates than requested, the app will use the maximum available without repeating a question.</div></div></main>''')
write('quiz.html','''<main class="container"><div class="quiz"><div class="qtop"><span id="qnum">Question</span><span id="score">Score: 0</span></div><div class="progress"><span id="bar" style="width:0"></span></div><div class="card"><div id="question" class="question">Loading…</div><div id="answerBox" style="margin-top:22px"></div><div class="actions"><button id="submit" class="btn primary">Submit answer</button><button id="next" class="btn secondary hidden">Next question →</button></div><div id="feedback" class="feedback hidden"></div>
<div id="answerReview" class="answer-review hidden"></div></div></div></main>''')
write('results.html','''<main class="container"><div class="result"><div class="card"><span class="eyebrow">Quiz complete</span><h1 id="headline">Results</h1><p id="message" class="lead" style="margin:0 auto"></p><div id="percent" class="score gradient">0%</div><div class="cards" style="margin-top:25px"><div class="card"><div class="muted">Questions</div><div class="stat"><div class="num" id="total">0</div></div></div><div class="card"><div class="muted">Correct</div><div class="stat"><div class="num" id="correct">0</div></div></div><div class="card"><div class="muted">Wrong</div><div class="stat"><div class="num" id="wrong">0</div></div></div></div><p class="muted">Performance: <b id="level"></b></p><div class="actions" style="justify-content:center"><a class="btn primary" href="student.html">Start another quiz →</a><a class="btn secondary" href="index.html">Back to Home</a><a class="btn secondary" href="progress.html">View Progress</a></div><div id="review"></div></div></div></main>''')
write('progress.html','''<main class="container section"><span class="eyebrow">Learning dashboard</span><h1>Concord’s Learning Progress</h1><p class="muted">Student: <b id="name"></b></p><div class="cards" style="margin:25px 0"><div class="card"><div class="muted">Average score</div><div class="stat"><div class="num" id="avg">0%</div></div></div><div class="card"><div class="muted">Best score</div><div class="stat"><div class="num" id="best">0%</div></div></div><div class="card"><div class="muted">Attempts</div><div class="stat"><div class="num" id="attempts">—</div></div></div></div><div id="list"></div></main>''','''<script>document.addEventListener('DOMContentLoaded',()=>{const d=getDB();const e=document.querySelector('#attempts');if(e)e.textContent=d.results.length})</script>''')
write('about.html','''<main class="container section"><div class="card"><span class="eyebrow">About the tutor</span><h1>Concord’s as your Tutor</h1><p class="lead">A local-first study companion that turns your own notes into practice questions, gives immediate feedback, and keeps a simple record of your quiz performance.</p><div class="cards"><div class="card feature"><div class="ico">🔒</div><h3>Privacy-minded</h3><p>Profile, quiz history and extracted study text are stored in your browser. This static build does not upload files to a remote server.</p></div><div class="card feature"><div class="ico">🧠</div><h3>Material-based</h3><p>The question builder uses sentences and concepts found in your material. It does not intentionally invent outside subject matter.</p></div><div class="card feature"><div class="ico">🌗</div><h3>Study anywhere</h3><p>Responsive pages, dark/light mode and normal HTML links make the app usable across phones and computers.</p></div></div><div class="actions"><a href="index.html" class="btn primary">Home</a><a href="upload.html" class="btn secondary">Upload material</a><button id="reset" class="btn danger">Reset profile & progress</button></div></div></main>''')
